WITH target(id, name, city) AS (
  VALUES (1, 'Ada', 'Oslo'), (2, 'Ben', 'Lyon'), (3, 'Chloe', 'Porto')
), batch(id, name, city) AS (
  VALUES (2, 'Ben', 'Paris'), (4, 'Dina', 'Rome')
), upserted AS (
  SELECT id, name, city FROM batch
  UNION ALL
  SELECT t.id, t.name, t.city FROM target t
  WHERE NOT EXISTS (SELECT 1 FROM batch b WHERE b.id = t.id)
)
SELECT * FROM upserted ORDER BY id;
